-- ============================================================================
-- NumberShield - Supabase PostgreSQL Schema & Seed Script
-- ============================================================================
-- Run this script in your Supabase SQL Editor:
-- Dashboard -> SQL Editor -> New Query -> Paste & Run
-- ============================================================================

-- 1. Services Table
CREATE TABLE IF NOT EXISTS public.services (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    note TEXT NOT NULL
);

-- 2. Consents Table
CREATE TABLE IF NOT EXISTS public.consents (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_id BIGINT UNIQUE NOT NULL REFERENCES public.services(id) ON DELETE CASCADE,
    status TEXT NOT NULL CHECK (status IN ('allowed', 'denied', 'withdrawn')),
    updated_at TEXT NOT NULL DEFAULT (timezone('utc'::text, now())::text)
);

-- 3. Exposures Table
CREATE TABLE IF NOT EXISTS public.exposures (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_id BIGINT NOT NULL REFERENCES public.services(id) ON DELETE CASCADE,
    exposure_type TEXT NOT NULL,
    severity TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high')),
    evidence TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (timezone('utc'::text, now())::text)
);

-- 4. Privacy Requests Table
CREATE TABLE IF NOT EXISTS public.privacy_requests (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_id BIGINT NOT NULL REFERENCES public.services(id) ON DELETE CASCADE,
    request_type TEXT NOT NULL CHECK (request_type IN ('deletion', 'consent_withdrawal', 'access')),
    status TEXT NOT NULL DEFAULT 'draft',
    reference TEXT UNIQUE NOT NULL,
    draft_text TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (timezone('utc'::text, now())::text)
);

-- 5. Audit Logs Table
CREATE TABLE IF NOT EXISTS public.audit_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    action TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id BIGINT NOT NULL,
    details TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (timezone('utc'::text, now())::text)
);

-- ============================================================================
-- Row Level Security (RLS) & Access Policies
-- ============================================================================
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.consents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.exposures ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.privacy_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;

-- Allow read/write access for application operations
DO $$ 
BEGIN
    DROP POLICY IF EXISTS "Allow all access on services" ON public.services;
    CREATE POLICY "Allow all access on services" ON public.services FOR ALL USING (true) WITH CHECK (true);

    DROP POLICY IF EXISTS "Allow all access on consents" ON public.consents;
    CREATE POLICY "Allow all access on consents" ON public.consents FOR ALL USING (true) WITH CHECK (true);

    DROP POLICY IF EXISTS "Allow all access on exposures" ON public.exposures;
    CREATE POLICY "Allow all access on exposures" ON public.exposures FOR ALL USING (true) WITH CHECK (true);

    DROP POLICY IF EXISTS "Allow all access on privacy_requests" ON public.privacy_requests;
    CREATE POLICY "Allow all access on privacy_requests" ON public.privacy_requests FOR ALL USING (true) WITH CHECK (true);

    DROP POLICY IF EXISTS "Allow all access on audit_logs" ON public.audit_logs;
    CREATE POLICY "Allow all access on audit_logs" ON public.audit_logs FOR ALL USING (true) WITH CHECK (true);
END $$;

