-- Reset sequences to prevent key collisions
SELECT setval(pg_get_serial_sequence('public.services', 'id'), COALESCE(max(id), 1)) FROM public.services;
SELECT setval(pg_get_serial_sequence('public.consents', 'id'), COALESCE(max(id), 1)) FROM public.consents;
SELECT setval(pg_get_serial_sequence('public.exposures', 'id'), COALESCE(max(id), 1)) FROM public.exposures;
SELECT setval(pg_get_serial_sequence('public.privacy_requests', 'id'), COALESCE(max(id), 1)) FROM public.privacy_requests;
SELECT setval(pg_get_serial_sequence('public.audit_logs', 'id'), COALESCE(max(id), 1)) FROM public.audit_logs;
